95	    /** A claim's figure now: the due fixed when it was settled, else the one its last statement bound
96	     *  it to, else its live due; null when it has none. */
97	    public BigDecimal figure(String sheetId, Claim claim) {
98	        if (claim.due() != null) return new BigDecimal(claim.due());
99	        if (claim.stated() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
100	        return due(sheetId, claim);
101	    }
