103	    /** Whether a rate for the person's grade is in force on a date. */
104	    public boolean rated(String sheetId, long personId, LocalDate on) {
105	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM rate r JOIN person p ON p.sheet_id = r.sheet_id"
106	                + " AND p.grade = r.grade WHERE p.sheet_id = ? AND p.id = ?"
107	                + " AND (r.from_date IS NULL OR r.from_date <= ?)", Integer.class, sheetId, personId, Date.valueOf(on));
108	        return n != null && n > 0;
109	    }
