112	    public void bind(String sheetId, long claimId, boolean stated, BigDecimal figure) {
113	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE id = ? AND sheet_id = ?", stated, figure,
114	                claimId, sheetId);
