117	    /** A person's claims on the sheet. */
118	    public List<Claim> ofPerson(String sheetId, long personId) {
119	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
120	                ROW, sheetId, personId);
121	    }
