123	    /** Fix a settled claim's due. */
124	    public void settleDue(String sheetId, long claimId, BigDecimal due) {
125	        jdbc.update("UPDATE claim SET settled_due = ? WHERE id = ? AND sheet_id = ?", due, claimId, sheetId);
