150	    /** Change a DRAFT claim's amount, date and note; false when the sheet has no such draft claim. */
151	    public boolean update(String sheetId, long claimId, BigDecimal amount, LocalDate date, String note) {
152	        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ? WHERE id = ? AND sheet_id = ?"
