209	/** Move a claim along its status: open, settle or void, each only from the statuses it allows. */
210	public class ChangeClaimStatus {
211	    public void change(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
212	            @PathVariable("action") String action, ServerHttpConnection connection, ClaimRepository repository,
213	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
214	        String by = CurrentUser.require(connection);
215	        String id = sheetId == null ? "" : sheetId.trim();
216	        long cid;
217	        try {
218	            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
219	        } catch (NumberFormatException e) {
220	            throw new BadRequestException("no such claim");
221	        }
222	        String to;
223	        List<String> from;
224	        String event;
225	        switch (action == null ? "" : action.trim()) {
226	            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
227	            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
228	            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN"); event = "CLAIM_VOIDED"; }
229	            default -> throw new BadRequestException("no such action");
230	        }
231	        Claim found = repository.find(id, cid);
232	        if (found == null) {
233	            throw new BadRequestException("no such claim");
234	        }
235	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
236	        // Four eyes: whoever opened a claim cannot settle it.
237	        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
238	            throw new BadRequestException("the user who opened a claim cannot settle it");
239	        }
240	        // A clerk settles only a claim whose due is within the sheet's clerk limit ('n/a' is within any);
241	        // a steward settles anything.
242	        if (to.equals("SETTLED") && found.status().equals("OPEN")
243	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
244	            BigDecimal limit = settings.clerkLimit(id);
245	            BigDecimal now = repository.figure(id, found);
246	            if (limit != null && now != null && now.compareTo(limit) > 0) {
247	                throw new BadRequestException("a clerk cannot settle a claim whose due is above the clerk limit of "
248	                        + SettingsRepository.money(limit));
249	            }
250	        }
251	        Rollup.Snapshot before = rollup.take(id);
252	        if (!repository.changeStatus(id, cid, from, to)) {
253	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
254	        }
255	        // Opening gives the sheet's next number; a voided claim keeps the number it had (never reused).
256	        Long number = found.number();
257	        String openedBy = found.openedBy();
258	        if (to.equals("OPEN")) {
259	            number = repository.number(id, cid);
260	            repository.openedBy(id, cid, by);
261	            openedBy = by;
262	        }
263	        // Settling fixes the claim's due as it is now: the figure its last statement bound it to, else its
264	        // live due ('n/a' when its grade has no rate, which stays live).
265	        String due = null;
266	        String settledDue = "";
267	        if (to.equals("SETTLED")) {
268	            BigDecimal now = repository.figure(id, found);
269	            repository.settleDue(id, cid, now);
270	            due = ClaimRepository.dueOf(now);
271	            settledDue = " due=" + (due == null ? "n/a" : due);
272	        }
273	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
274	                number, due, openedBy, found.stated(), found.statedDue());
275	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
276	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + settledDue);
277	        rollup.record(id, by, before);
278	        claim.set(changed);
279	    }
280	}
