298	/** Take a person's statement: record their due-total now, and bind each claim of theirs that counts
299	 *  to the figure it has now (a settled claim keeps its frozen due); a claim that does not count is
300	 *  unbound (live again). The due-total is as shown: the sum of the counting claims' figures, skipping
301	 *  those with none; 'n/a' when no rate for their grade is in force on the sheet's today and no
302	 *  counting claim has a fixed figure. */
303	public class TakeStatement {
304	    public void take(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
305	            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims,
306	            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException {
307	        String by = CurrentUser.require(connection);
308	        String id = sheetId == null ? "" : sheetId.trim();
309	        long pid;
310	        try {
311	            pid = Long.parseLong(personId == null ? "" : personId.trim());
312	        } catch (NumberFormatException e) {
313	            throw new BadRequestException("no such person");
314	        }
315	        Person found = people.find(id, pid);
316	        if (found == null) {
317	            throw new BadRequestException("no such person");
318	        }
319	        LocalDate today = sheets.today(id);
320	        Rollup.Snapshot before = rollup.take(id);
321	        BigDecimal total = BigDecimal.ZERO.setScale(2);
322	        boolean fixed = false;
323	        int count = 0;
324	        for (Claim c : claims.ofPerson(id, pid)) {
325	            if (!c.counts()) {
326	                claims.bind(id, c.id(), false, null);
327	                continue;
328	            }
329	            count++;
330	            fixed |= c.due() != null || (c.stated() && c.statedDue() != null);
331	            BigDecimal figure = claims.figure(id, c);
332	            if (figure != null) {
333	                total = total.add(figure);
334	            }
335	            claims.bind(id, c.id(), true, figure);
336	        }
337	        String dueTotal = fixed || claims.rated(id, pid, today) ? total.setScale(2).toPlainString() : "n/a";
338	        people.stated(id, pid, dueTotal, today);
339	        audit.record("STATEMENT sheet=" + id + " by=" + by + " name=" + found.name() + " due-total=" + dueTotal
340	                + " claims=" + count);
341	        rollup.record(id, by, before);
342	        person.set(people.find(id, pid));
343	    }
344	}
