359	
360	/** The sheet's figures as shown: each person's claimed and due-total, and the sheet's claimed-total and
361	 *  due-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
362	 *  line per person whose figures moved (people in the order they were added; a new person counts as
363	 *  moved), then a TOTALS line when the sheet's totals moved. */
364	@Service
365	public class Rollup {
366	
367	    /** A person's figures: claimed (two decimals) and due-total (two decimals, or 'n/a'). */
368	    record Figures(String name, String claimed, String dueTotal) {
369	        boolean same(Figures other) {
370	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
371	        }
372	    }
373	
374	    /** The figures of a sheet at one moment, people by id in the order they were added. */
375	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
376	    }
377	
378	    private final PersonRepository people;
379	    private final ClaimRepository claims;
380	    private final SheetRepository sheets;
381	    private final Audit audit;
382	
383	    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, Audit audit) {
384	        this.people = people;
385	        this.claims = claims;
386	        this.sheets = sheets;
387	        this.audit = audit;
388	    }
389	
390	    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures,
391	     *  skipping those with none; 'n/a' when no rate for their grade is in force on the sheet's today and
392	     *  no counting claim keeps a fixed figure. The sheet's due-total skips 'n/a'. */
393	    public Snapshot take(String sheetId) {
394	        List<Person> everyone = people.list(sheetId);
395	        Map<Long, Figures> figures = new LinkedHashMap<>();
396	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
397	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
398	        if (!everyone.isEmpty()) {
399	            LocalDate today = sheets.today(sheetId);
400	            List<Claim> all = claims.list(sheetId);
401	            for (Person p : everyone) {
402	                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
403	                BigDecimal due = BigDecimal.ZERO.setScale(2);
404	                boolean fixed = false;
405	                for (Claim c : all) {
406	                    if (c.personId() != p.id() || !c.counts(p.held())) continue;
407	                    claimed = claimed.add(new BigDecimal(c.amount()));
408	                    fixed |= c.due() != null || (c.stated() && c.statedDue() != null);
409	                    BigDecimal figure = claims.figure(sheetId, c);
410	                    if (figure != null) due = due.add(figure);
411	                }
412	                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
413	                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
414	                        shown ? due.toPlainString() : "n/a"));
415	                claimedTotal = claimedTotal.add(claimed);
416	                if (shown) dueTotal = dueTotal.add(due);
417	            }
418	        }
419	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
420	    }
421	
422	    /** Record the lines for whatever figures moved since {@code before}. */
423	    public void record(String sheetId, String by, Snapshot before) {
424	        Snapshot after = take(sheetId);
425	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
426	            Figures now = e.getValue();
427	            if (now.same(before.people().get(e.getKey()))) continue;
428	            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
429	                    + now.claimed() + " due-total=" + now.dueTotal());
430	        }
431	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
432	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
433	                    + " due-total=" + after.dueTotal());
434	        }
435	    }
436	}
