563	    private final JdbcTemplate jdbc;
564	
565	    public SettingsRepository(JdbcTemplate jdbc) {
566	        this.jdbc = jdbc;
567	    }
568	
569	    public boolean sheetExists(String sheetId) {
570	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
571	        return known != null && known > 0;
572	    }
573	
574	    /** The sheet's settings and roles, roles by user name. */
575	    public Settings load(String sheetId) {
576	        List<Role> roles = jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
577	                (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role")), sheetId);
578	        BigDecimal limit = clerkLimit(sheetId);
579	        return new Settings(limit == null ? null : money(limit), money(floor(sheetId)), terms(sheetId), roles);
580	    }
