582	    /** The sheet's clerk limit; null when it has none. */
583	    public BigDecimal clerkLimit(String sheetId) {
584	        List<BigDecimal> found = jdbc.query("SELECT clerk_limit FROM sheet WHERE id = ?",
585	                (rs, i) -> rs.getBigDecimal("clerk_limit"), sheetId);
586	        return found.isEmpty() ? null : found.get(0);
