package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made empty (its today the real date) when the id was never used. */
    public Sheet loadOrCreate(String id, String user) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
        if (known == null || known == 0) {
            try {
                jdbc.update("INSERT INTO sheet (id, created_by, today) VALUES (?, ?, ?)", id, user,
                        Date.valueOf(LocalDate.now()));
            } catch (DuplicateKeyException made) {
                // another user loaded the same new id at the same moment: it is made either way
            }
        }
        return new Sheet(id, today(id).toString());
    }

    /** The sheet's today: the date every date decision and default in the sheet uses. */
    public LocalDate today(String id) {
        Date today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, id);
        return today.toLocalDate();
    }

    /** Set the sheet's today; false when there is no such sheet. */
    public boolean setToday(String id, LocalDate today) {
        return jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id) > 0;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Close a period: fix its due-total as shown now (the figures of the counting claims dated in it, a held
 *  person's OPEN claims left out,
 *  skipping those with none), so later changes to rates do not alter it. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            ServerHttpConnection connection, PeriodRepository repository, ClaimRepository claims, PersonRepository people, Audit audit,
            Out<Period> period) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        Period found = repository.find(id, periodName == null ? "" : periodName.trim());
        if (found == null) {
            throw new BadRequestException("no such period");
        }
        if (found.closed()) {
            throw new BadRequestException("the period " + found.name() + " is already closed");
        }
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Set<Long> held = people.heldIds(id);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(id)) {
            LocalDate on = LocalDate.parse(c.date());
            if (!c.counts(held.contains(c.personId())) || on.isBefore(from) || on.isAfter(to)) continue;
            BigDecimal figure = claims.figure(id, c);
            if (figure != null) total = total.add(figure);
        }
        String shown = total.setScale(2).toPlainString();
        repository.close(id, found.id(), total);
        audit.record("PERIOD_CLOSED sheet=" + id + " by=" + by + " period=" + found.name() + " total=" + shown);
        period.set(new Period(found.id(), found.name(), found.from(), found.to(), true, shown));
    }
}
